#!/usr/bin/env node
/**
 * The whole-quote fingerprints of the price gate (specs/pricing-components.md §3 rules 4 and 68).
 *
 *   DB_PATH=:memory: node scripts/price-gate/buildQuoteHashes.js <capturedAt ISO> <inputs.json> <production|synthetic> <out.json>
 *
 * Loads the anonymised rows of `inputs.json` (the production tables, or the `synthetic` section) into a fresh database, freezes the
 * clock and writes `{ [reservationId]: { keys, hash } }` (`recompute.js` `quoteHashesOf`). Run by `buildFixture.mjs` on the
 * baseline code, in a process of its own; never regenerated by PR A, B or C. Prints the number of stays only.
 */
const fs = require('node:fs');
const path = require('node:path');

const [capturedAt, inputsFile, section, outFile] = process.argv.slice(2);
if (!capturedAt || !inputsFile || !['production', 'synthetic'].includes(section) || !outFile || process.env.DB_PATH !== ':memory:') {
  console.error('usage: DB_PATH=:memory: buildQuoteHashes.js <capturedAt ISO> <inputs.json> <production|synthetic> <out.json>');
  process.exit(2);
}
process.env.TZ = 'Europe/Paris';
const root = path.resolve(__dirname, '..', '..');
const { freezeClock } = require(path.join(root, 'server/src/tests/vatRegimeGoldenFixture.js'));
freezeClock(new Date(capturedAt));

const print = console.log;
console.log = () => {};
const inputs = JSON.parse(fs.readFileSync(inputsFile, 'utf8'));
const db = require(path.join(root, 'server/src/database.js'));
const { loadInputs, quoteHashesOf } = require('./recompute.js');
loadInputs(db, section === 'synthetic' ? { tables: inputs.synthetic.tables } : inputs);
const hashes = quoteHashesOf(db);
fs.writeFileSync(outFile, `${JSON.stringify(hashes, null, 1)}\n`);
console.log = print;
print(`${section}: ${Object.keys(hashes).length} quote fingerprints`);
